{{ config(
            materialized='table',
                post_hook={
                    "sql": "DROP TABLE IF EXISTS public.GS_State_ISO; CREATE TABLE public.GS_State_ISO ( state VARCHAR(256), iso_code VARCHAR(10) ); DROP TABLE IF EXISTS public.Final_customerID; CREATE TABLE public.Final_customerID AS WITH new_phone_numbers AS ( SELECT phone, email, contact_num, 19700000000 + DENSE_RANK() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT RIGHT(REGEXP_REPLACE(phone, \'[^a-zA-Z0-9]+\', \'\'), 10) AS contact_num, email, phone FROM public.tuco_kids_sales_consolidated_intermediate WHERE phone IS NOT NULL ) a ), INT AS ( SELECT contact_num, email, COALESCE(maple_monk_id, id2) AS maple_monk_id FROM ( SELECT contact_num, email, maple_monk_id, 19800000000 + ROW_NUMBER() OVER (PARTITION BY maple_monk_id IS NULL ORDER BY email ASC) AS id2 FROM ( SELECT DISTINCT COALESCE(p.contact_num, RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10)) AS contact_num, e.email, COALESCE(p.maple_monk_id, pe.maple_monk_id) AS maple_monk_id FROM ( SELECT phone AS contact_num, email FROM public.tuco_kids_sales_consolidated_intermediate ) e LEFT JOIN new_phone_numbers p ON p.contact_num = RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10) LEFT JOIN ( SELECT * FROM ( SELECT * , ROW_NUMBER() OVER (PARTITION BY LOWER(email) ORDER BY 1) AS rn FROM new_phone_numbers ) sub WHERE rn = 1 ) pe ON LOWER(pe.email) = LOWER(e.email) ) b ) ) SELECT contact_num, email, maple_monk_id FROM INT WHERE COALESCE(contact_num, email) IS NOT NULL; DROP TABLE IF EXISTS public.tuco_kids_sales_consolidated; CREATE TABLE public.tuco_kids_sales_consolidated AS SELECT COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS customer_id_final, MIN(order_date) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS acquisition_date, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN order_date END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS first_complete_order_date, SUM(COALESCE(quantity, 0)) OVER (PARTITION BY reference_code) AS Order_Quantity, CASE WHEN (ABS(selling_price) > 10 AND (order_type IS NULL OR NOT (order_type IN (\'Test Order\',\'Photoshoot Order\',\'Stock Transfer Order\',\'Raw Material Order\',\'Influencer Order\',\'Return Prime Order\')))) THEN \'Gross Sale Orders\' ELSE \'Gross Orders\' END AS GROSS_ORDER_TYPE, CASE WHEN m.pincode LIKE \'1%\' OR m.pincode LIKE \'2%\' THEN \'North Region\' WHEN m.pincode LIKE \'3%\' OR m.pincode LIKE \'4%\' THEN \'West Region\' WHEN m.pincode LIKE \'5%\' OR m.pincode LIKE \'6%\' THEN \'South Region\' WHEN m.pincode LIKE \'7%\' OR m.pincode LIKE \'8%\' THEN \'East Region\' ELSE NULL END AS region, iso.iso_code AS state_iso_code, m.* FROM ( SELECT c.maple_monk_id AS maple_monk_id_phone, o.* FROM public.tuco_kids_sales_consolidated_intermediate o LEFT JOIN ( SELECT * FROM ( SELECT contact_num AS phone, maple_monk_id, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY maple_monk_id ASC) AS magic FROM public.Final_customerID ) WHERE magic = 1 ) c ON c.phone = RIGHT(REGEXP_REPLACE(o.phone, \'[^a-zA-Z0-9]+\', \'\'), 10) ) m LEFT JOIN ( SELECT DISTINCT maple_monk_id, email FROM public.Final_customerID WHERE contact_num IS NULL ) d ON d.email = m.email LEFT JOIN ( SELECT * FROM public.GS_State_ISO ) iso ON LOWER(REPLACE(iso.state, \' \', \'\')) = LOWER(REPLACE(m.state, \' \', \'\')); ALTER TABLE public.tuco_kids_sales_consolidated DROP COLUMN new_customer_flag; ALTER TABLE public.tuco_kids_sales_consolidated DROP COLUMN acquisition_product; ALTER TABLE public.tuco_kids_sales_consolidated ADD COLUMN new_customer_flag VARCHAR(256); ALTER TABLE public.tuco_kids_sales_consolidated ADD COLUMN new_customer_flag_month VARCHAR(256); ALTER TABLE public.tuco_kids_sales_consolidated ADD COLUMN acquisition_product VARCHAR(256); ALTER TABLE public.tuco_kids_sales_consolidated ADD COLUMN acquisition_channel VARCHAR(256); ALTER TABLE public.tuco_kids_sales_consolidated ADD COLUMN acquisition_marketplace VARCHAR(256); UPDATE public.tuco_kids_sales_consolidated SET new_customer_flag = B.flag FROM ( SELECT order_id, customer_id_final, order_date, CASE WHEN order_date = first_complete_order_date THEN \'New\' WHEN order_date < first_complete_order_date OR first_complete_order_date IS NULL THEN \'Yet to make completed order\' WHEN order_date > first_complete_order_date THEN \'Repeat\' END AS flag, ROW_NUMBER() OVER ( PARTITION BY order_id, customer_id_final ORDER BY order_date ) AS rw FROM public.tuco_kids_sales_consolidated ) AS B WHERE public.tuco_kids_sales_consolidated.order_id = B.order_id AND public.tuco_kids_sales_consolidated.customer_id_final = B.customer_id_final AND B.rw = 1; UPDATE public.tuco_kids_sales_consolidated SET new_customer_flag = CASE WHEN new_customer_flag IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' WHEN new_customer_flag IS NULL AND LOWER(order_status) IN (\'cancelled\') THEN \'Yet to make completed order\' ELSE new_customer_flag END WHERE new_customer_flag IS NULL; UPDATE public.tuco_kids_sales_consolidated SET new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, order_date, CASE WHEN DATE_TRUNC(\'month\', order_date) = DATE_TRUNC(\'month\', first_complete_order_date) THEN \'New\' WHEN DATE_TRUNC(\'month\', order_date) < DATE_TRUNC(\'month\', first_complete_order_date) OR acquisition_date IS NULL THEN \'Yet to make completed order\' WHEN DATE_TRUNC(\'month\', order_date) > DATE_TRUNC(\'month\', first_complete_order_date) THEN \'Repeat\' END AS flag, ROW_NUMBER() OVER (PARTITION BY order_id, customer_id_final ORDER BY order_date) AS rw FROM public.tuco_kids_sales_consolidated ) AS B WHERE public.tuco_kids_sales_consolidated.order_id = B.order_id AND public.tuco_kids_sales_consolidated.customer_id_final = B.customer_id_final AND B.rw = 1; UPDATE public.tuco_kids_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' ELSE new_customer_flag_month END WHERE new_customer_flag_month IS NULL; DROP TABLE IF EXISTS temp_source_1; CREATE TEMPORARY TABLE temp_source_1 AS SELECT customer_id_final, source AS channel, shop_name AS marketplace FROM ( SELECT * FROM( SELECT customer_id_final, order_date, source, shop_name, MIN(CASE WHEN LOWER(order_status) != \'cancelled\' THEN order_date END) OVER (PARTITION BY customer_id_final) AS firstOrderDate, ROW_NUMBER() OVER (PARTITION BY customer_id_final ORDER BY ORDER_TIME) AS rw FROM public.tuco_kids_sales_consolidated ) AS res WHERE rw = 1 ) WHERE order_date = firstOrderDate; UPDATE public.tuco_kids_sales_consolidated SET acquisition_channel = b.channel FROM temp_source_1 AS b WHERE public.tuco_kids_sales_consolidated.customer_id_final = b.customer_id_final; UPDATE public.tuco_kids_sales_consolidated SET acquisition_marketplace = b.marketplace FROM temp_source_1 AS b WHERE public.tuco_kids_sales_consolidated.customer_id_final = b.customer_id_final; DROP TABLE IF EXISTS temp_product_1; CREATE TEMPORARY TABLE temp_product_1 AS SELECT customer_id_final, product_name_final FROM ( SELECT customer_id_final, order_date, product_name_final, SELLING_PRICE, MIN(CASE WHEN LOWER(order_status) != \'cancelled\' THEN order_date END) OVER (PARTITION BY customer_id_final) AS firstOrderdate, ROW_NUMBER() OVER (PARTITION BY customer_id_final ORDER BY ORDER_TIME ASC, selling_price DESC) AS rw FROM public.tuco_kids_sales_consolidated ) res WHERE order_date = firstorderdate AND rw = 1; UPDATE public.tuco_kids_sales_consolidated SET acquisition_product = B.product_name_final FROM ( SELECT * FROM temp_product_1 ) AS B WHERE public.tuco_kids_sales_consolidated.customer_id_final = B.customer_id_final; UPDATE public.tuco_kids_sales_consolidated SET state = CASE WHEN UPPER(state) IN (\'AP\', \'ANDHRA PRADESH\', \'ANDHRAPRADESH\') THEN \'ANDHRA PRADESH\' WHEN UPPER(state) IN (\'AR\', \'ARUNACHAL PRADESH\') THEN \'ARUNACHAL PRADESH\' WHEN UPPER(state) IN (\'AS\', \'ASSAM\', \'ASSAM HINDUISM\') THEN \'ASSAM\' WHEN UPPER(state) IN (\'BR\', \'BIHAR\') THEN \'BIHAR\' WHEN UPPER(state) IN (\'CT\', \'CHHATTISGARH\', \'CHATTISGARH\', \'CHHATISGARH\') THEN \'CHHATTISGARH\' WHEN UPPER(state) IN (\'GA\', \'GOA\') THEN \'GOA\' WHEN UPPER(state) IN (\'GJ\', \'GUJARAT\', \'GUJRAT\') THEN \'GUJARAT\' WHEN UPPER(state) IN (\'HR\', \'HARYANA\') THEN \'HARYANA\' WHEN UPPER(state) IN (\'HP\', \'HIMACHAL PRADESH\', \'HIMANCHAL PRADESH\') THEN \'HIMACHAL PRADESH\' WHEN UPPER(state) IN (\'JH\', \'JHARKHAND\') THEN \'JHARKHAND\' WHEN UPPER(state) IN (\'KA\', \'KARNATAKA\', \'KARANATAKA\', \'KARNATKA\') THEN \'KARNATAKA\' WHEN UPPER(state) IN (\'KL\', \'KERALA\') THEN \'KERALA\' WHEN UPPER(state) IN (\'MP\', \'MADHYA PRADESH\', \'MADHYAPRADESH\', \'M. P\') THEN \'MADHYA PRADESH\' WHEN UPPER(state) IN (\'MH\', \'MAHARASHTRA\', \'MAHARASTRA\', \'MAHARASHATRA\', \'MAHASHTRA\', \'MUMBAI THANA\') THEN \'MAHARASHTRA\' WHEN UPPER(state) IN (\'MN\', \'MANIPUR\') THEN \'MANIPUR\' WHEN UPPER(state) IN (\'ML\', \'MEGHALAYA\', \'MEGALAYA\') THEN \'MEGHALAYA\' WHEN UPPER(state) IN (\'MZ\', \'MIZORAM\') THEN \'MIZORAM\' WHEN UPPER(state) IN (\'NL\', \'NAGALAND\') THEN \'NAGALAND\' WHEN UPPER(state) IN (\'OR\', \'ODISHA\', \'ORISSA\') THEN \'ODISHA\' WHEN UPPER(state) IN (\'PB\', \'PUNJAB\') THEN \'PUNJAB\' WHEN UPPER(state) IN (\'RJ\', \'RAJASTHAN\') THEN \'RAJASTHAN\' WHEN UPPER(state) IN (\'SK\', \'SIKKIM\') THEN \'SIKKIM\' WHEN UPPER(state) IN (\'TN\', \'TAMIL NADU\', \'TAMILNADU\') THEN \'TAMIL NADU\' WHEN UPPER(state) IN (\'TS\', \'TL\', \'TELANGANA\') THEN \'TELANGANA\' WHEN UPPER(state) IN (\'TR\', \'TRIPURA\') THEN \'TRIPURA\' WHEN UPPER(state) IN (\'UP\', \'UTTAR PRADESH\', \'UTTER PRADESH\') THEN \'UTTAR PRADESH\' WHEN UPPER(state) IN (\'UT\', \'UK\', \'UTTARAKHAND\', \'UTTRAKHAND\') THEN \'UTTARAKHAND\' WHEN UPPER(state) IN (\'WB\', \'WEST BENGAL\', \'WEST BANGAL\', \'WB(KOLKATA & HOWRAH AREA)\') THEN \'WEST BENGAL\' WHEN UPPER(state) IN (\'AN\', \'ANDAMAN AND NICOBAR ISLANDS\', \'ANDAMAN & NICOBAR ISLANDS\') THEN \'ANDAMAN AND NICOBAR ISLANDS\' WHEN UPPER(state) IN (\'CH\', \'CHANDIGARH\') THEN \'CHANDIGARH\' WHEN UPPER(state) IN (\'DN\', \'DADRA AND NAGAR HAVELI\', \'DADRA & NAGAR HAVELI\', \'DD\', \'DAMAN AND DIU\', \'DAMAN & DIU\', \'DADRA & NAGAR HAVELI AND DAMAN & DIU\', \'DADRA AND NAGAR HAVELI AND DAMAN AND DIU\', \'DADRA AND NAGAR HAV.\') THEN \'DADRA AND NAGAR HAVELI AND DAMAN AND DIU\' WHEN UPPER(state) IN (\'LD\', \'LAKSHADWEEP\') THEN \'LAKSHADWEEP\' WHEN UPPER(state) IN (\'DL\', \'DELHI\', \'NEW DELHI\', \'NCR\') THEN \'DELHI\' WHEN UPPER(state) IN (\'PY\', \'PUDUCHERRY\', \'PONDICHERRY\') THEN \'PUDUCHERRY\' WHEN UPPER(state) IN (\'JK\', \'JAMMU AND KASHMIR\', \'JAMMU & KASHMIR\') THEN \'JAMMU AND KASHMIR\' WHEN UPPER(state) = \'LADAKH\' THEN \'LADAKH\' WHEN UPPER(state) IN (\'AUCKLAND\', \'UNITED KINGDOM (+44)\', \'NON-US\', \'ZEELAND\', \'SINGAPORE\', \'BARCELONA\') THEN NULL WHEN UPPER(state) IN (\'INDIA\', \'1493\', \'BJP.TEAM211@GMAIL.COM\') THEN NULL WHEN UPPER(state) IN (\'NOT SPECIFIED\', \'\') THEN NULL ELSE state END; DROP TABLE IF EXISTS public.tuco_kids_sales_consolidated_final; CREATE TABLE public.tuco_kids_sales_consolidated_final AS SELECT customer_id_final, acquisition_date, first_complete_order_date, Order_Quantity, tags, GROSS_ORDER_TYPE, region, maple_monk_id_phone, customer_id, SHOP_NAME, marketplace, CHANNEL, SOURCE, ORDER_ID, reference_code, PHONE, NAME, EMAIL, SHIPPING_LAST_UPDATE_DATE, SKU, PRODUCT_ID, PRODUCT_NAME, CURRENCY, CITY, State, ORDER_STATUS, Order_Date, Order_Time, QUANTITY, GROSS_SALES_BEFORE_TAX, DISCOUNT, TAX, SHIPPING_PRICE, SELLING_PRICE, OMS_order_status, SHIPPING_STATUS, FINAL_SHIPPING_STATUS, SALEORDERITEMCODE, SALES_ORDER_ITEM_ID, AWB, PAYMENT_GATEWAY, payment_mode, COURIER, DISPATCH_DATE, DELIVERED_DATE, DELIVERED_STATUS, RETURN_FLAG, returned_quantity, returned_sales, cancelled_quantity, Days_in_Shipment, MARKETPLACE_ACQUISITION_DATE, SKU_CODE, PRODUCT_NAME_FINAL, PRODUCT_CATEGORY, PRODUCT_SUB_CATEGORY, commonsku, WAREHOUSE, pincode, source_pincode, Source_name, Mapped_Source_Name, Order_Type, invoice_date, week_type, refund_date_final, refund_value, new_customer_flag, new_customer_flag_month, acquisition_product, acquisition_channel, acquisition_marketplace, NULL::NUMERIC AS shopify_refund_value, NULL::NUMERIC AS return_tax, cancelled_at, state_iso_code FROM public.tuco_kids_sales_consolidated UNION ALL SELECT NULL::BIGINT AS customer_id_final, NULL::DATE AS acquisition_date, NULL::DATE AS first_complete_order_date, NULL::NUMERIC AS Order_Quantity, NULL::VARCHAR(256) AS tags, CASE WHEN (ABS(refund_value) > 10 AND (order_type IS NULL OR NOT (order_type IN (\'Photoshoot Order\',\'Stock Transfer Order\',\'Raw Material Order\',\'Influencer Order\')))) THEN \'Gross Sale Orders\' ELSE \'Gross Orders\' END AS GROSS_ORDER_TYPE, region, maple_monk_id_phone, customer_id, SHOP_NAME, marketplace, CHANNEL, SOURCE, NULL::VARCHAR(256) AS ORDER_ID, NULL::VARCHAR(256) AS reference_code, NULL::VARCHAR(256) AS PHONE, NULL::VARCHAR(256) AS NAME, NULL::VARCHAR(256) AS EMAIL, NULL::TIMESTAMP AS SHIPPING_LAST_UPDATE_DATE, NULL::VARCHAR(256) AS SKU, NULL::VARCHAR(256) AS PRODUCT_ID, NULL::VARCHAR(256) AS PRODUCT_NAME, NULL::VARCHAR(256) AS CURRENCY, CITY, State, NULL::VARCHAR(256) AS ORDER_STATUS, refund_date_final AS Order_Date, NULL::TIMESTAMP AS Order_Time, NULL::NUMERIC AS QUANTITY, NULL::NUMERIC AS GROSS_SALES_BEFORE_TAX, NULL::NUMERIC AS DISCOUNT, NULL::NUMERIC AS TAX, NULL::NUMERIC AS SHIPPING_PRICE, NULL::NUMERIC AS SELLING_PRICE, NULL::VARCHAR(256) AS OMS_order_status, NULL::VARCHAR(256) AS SHIPPING_STATUS, NULL::VARCHAR(256) AS FINAL_SHIPPING_STATUS, NULL::VARCHAR(256) AS SALEORDERITEMCODE, NULL::VARCHAR(256) AS SALES_ORDER_ITEM_ID, NULL::VARCHAR(256) AS AWB, NULL::VARCHAR(256) AS PAYMENT_GATEWAY, NULL::VARCHAR(256) AS payment_mode, NULL::VARCHAR(256) AS COURIER, NULL::DATE AS DISPATCH_DATE, NULL::DATE AS DELIVERED_DATE, NULL::BIGINT AS DELIVERED_STATUS, NULL::BIGINT AS RETURN_FLAG, NULL::NUMERIC AS returned_quantity, NULL::NUMERIC AS returned_sales, NULL::BIGINT AS cancelled_quantity, NULL::BIGINT AS Days_in_Shipment, NULL::DATE AS MARKETPLACE_ACQUISITION_DATE, NULL::VARCHAR(256) AS SKU_CODE, NULL::VARCHAR(256) AS PRODUCT_NAME_FINAL, NULL::VARCHAR(256) AS PRODUCT_CATEGORY, NULL::VARCHAR(256) AS PRODUCT_SUB_CATEGORY, NULL::VARCHAR(256) AS commonsku, NULL::VARCHAR(256) AS WAREHOUSE, NULL::VARCHAR(20) AS pincode, NULL::VARCHAR(20) AS source_pincode, NULL::VARCHAR(256) AS Source_name, NULL::VARCHAR(256) AS Mapped_Source_Name, Order_Type, NULL::DATE AS invoice_date, NULL::VARCHAR(256) AS week_type, refund_date_final, refund_value, NULL::VARCHAR(256) AS new_customer_flag, NULL::VARCHAR(256) AS new_customer_flag_month, NULL::VARCHAR(256) AS acquisition_product, NULL::VARCHAR(256) AS acquisition_channel, NULL::VARCHAR(256) AS acquisition_marketplace, refund_value AS shopify_refund_value, tax AS return_tax, NULL::TIMESTAMP AS cancelled_at, state_iso_code FROM public.tuco_kids_sales_consolidated WHERE (LOWER(marketplace) LIKE \'%shopify%\' OR LOWER(marketplace) LIKE \'%website%\') AND COALESCE(refund_value, 0) > 0; DROP TABLE IF EXISTS public.tuco_kids_marketplace_pincode_analysis; CREATE TABLE public.tuco_kids_marketplace_pincode_analysis AS WITH pincode AS ( SELECT pincode, city, state, s.order_date, SUM(selling_price) AS pincode_sales, COUNT(DISTINCT CASE WHEN LOWER(marketplace) LIKE \'%website%\' THEN order_id END) AS Shopify_Orders, COUNT(DISTINCT CASE WHEN LOWER(marketplace) LIKE \'%amazon%\' THEN order_id END) AS Amazon_Orders, COUNT(DISTINCT CASE WHEN LOWER(marketplace) LIKE \'%myntra%\' THEN order_id END) AS Myntra_Orders, SUM(CASE WHEN LOWER(marketplace) LIKE \'%website%\' THEN quantity END) AS Shopify_Order_Quantity, SUM(CASE WHEN LOWER(marketplace) LIKE \'%amazon%\' THEN quantity END) AS Amazon_Order_Quantity, SUM(CASE WHEN LOWER(marketplace) LIKE \'%myntra%\' THEN quantity END) AS Myntra_Order_Quantity, SUM(CASE WHEN LOWER(marketplace) LIKE \'%website%\' THEN selling_price END) AS Shopify_Sales, SUM(CASE WHEN LOWER(marketplace) LIKE \'%amazon%\' THEN selling_price END) AS Amazon_Sales, SUM(CASE WHEN LOWER(marketplace) LIKE \'%myntra%\' THEN selling_price END) AS Myntra_Sales, COUNT(DISTINCT order_id) AS Total_Orders, SUM(COALESCE(quantity, 0)) AS Total_Order_Quantity, SUM(COALESCE(selling_price, 0)) AS Total_Sales, CASE WHEN SUM(COALESCE(quantity, 0)) = 0 THEN NULL ELSE CAST(COUNT(DISTINCT CASE WHEN LOWER(marketplace) LIKE \'%website%\' THEN order_id END) AS NUMERIC(10,4)) / CAST(COUNT(DISTINCT order_id) AS NUMERIC(10,4)) END AS D2C_Percentage_orders, CASE WHEN SUM(COALESCE(quantity, 0)) = 0 THEN NULL ELSE CAST(SUM(CASE WHEN LOWER(marketplace) LIKE \'%website%\' THEN COALESCE(quantity, 0) END) AS NUMERIC(10,4)) / CAST(SUM(COALESCE(quantity, 0)) AS NUMERIC(10,4)) END AS D2C_Percentage_order_quantity, CASE WHEN SUM(COALESCE(selling_price, 0)) = 0 THEN NULL ELSE CAST(SUM(CASE WHEN LOWER(marketplace) LIKE \'%website%\' THEN selling_price END) AS NUMERIC(10,4)) / CAST(SUM(COALESCE(selling_price, 0)) AS NUMERIC(10,4)) END AS D2C_Percentage_Sales FROM public.tuco_kids_sales_consolidated_final s WHERE GROSS_ORDER_TYPE = \'Gross Sale Orders\' GROUP BY 1, 2, 3, 4 ) SELECT p.*, p1.Shopify_Orders AS Shopify_Order_last_year, p1.Amazon_Orders AS Amazon_Order_last_year, p1.Myntra_Orders AS Myntra_Order_last_year, p1.Shopify_Order_Quantity AS Shopify_Order_Quantity_last_year, p1.Amazon_Order_Quantity AS Amazon_Order_Quantity_last_year, p1.Myntra_Order_Quantity AS Myntra_Order_Quantity_last_year, p1.Shopify_Sales AS Shopify_Sales_last_year, p1.Amazon_Sales AS Amazon_Sales_last_year, p1.Myntra_Sales AS Myntra_Sales_last_year, p1.Total_Orders AS Total_order_last_year, p1.Total_Order_Quantity AS Total_order_quantity_last_year, p1.Total_Sales AS Total_sales_last_year, p1.D2C_Percentage_orders AS D2C_Percentage_orders_last_year, p1.D2C_Percentage_order_quantity AS D2C_Percentage_order_quantity_last_year, p1.D2C_Percentage_sales AS D2C_Percentage_sales_last_year, p2.Shopify_Orders AS Shopify_Orders_last_month, p2.Shopify_Order_Quantity AS Shopify_Order_Quantity_last_month, p2.Shopify_Sales AS Shopify_Sales_last_month, p2.Total_Sales AS Total_Sales_last_month, p2.Total_Orders AS Total_Orders_last_month, p2.Total_Order_Quantity AS Total_Order_Quantity_last_month, CASE WHEN p.D2C_Percentage_orders = 0 THEN NULL ELSE (p1.D2C_Percentage_orders - p.D2C_Percentage_orders) / p.D2C_Percentage_orders END AS Rate_of_Change_of_D2C_percentage_orders_last_year, CASE WHEN p.D2C_Percentage_order_quantity = 0 THEN NULL ELSE (p1.D2C_Percentage_order_quantity - p.D2C_Percentage_order_quantity) / p.D2C_Percentage_order_quantity END AS Rate_of_Change_of_D2C_percentage_order_quantity_last_year, CASE WHEN p.D2C_Percentage_Sales = 0 THEN NULL ELSE (p1.D2C_Percentage_sales - p.D2C_Percentage_sales) / p.D2C_Percentage_sales END AS Rate_of_Change_of_D2C_percentage_sales_last_year, SUM(p.pincode_sales) OVER (PARTITION BY p.state, p.order_date) AS state_daily_sales, SUM(p.pincode_sales) OVER (PARTITION BY p.order_date) AS total_daily_sales FROM pincode p LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY pincode, order_date ORDER BY order_date DESC) AS rn FROM pincode ) sub WHERE rn = 1 ) p1 ON DATEADD(year, -1, p.order_date) = p1.order_date AND p.pincode = p1.pincode LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY pincode, order_date ORDER BY order_date DESC) AS rn FROM pincode ) sub WHERE rn = 1 ) p2 ON DATEADD(month, -1, p.order_date) = p2.order_date AND p.pincode = p2.pincode ;",
                    "transaction": true
